-- مخطط قاعدة بيانات نظام الصيدلية
-- Pharmacy POS schema (SQLite dialect, written to port to MySQL 8 with minimal changes).
--
-- Portability notes:
--   * Money is stored as whole Iraqi dinars in INTEGER columns (no floating point).
--   * Dates are DATE ('YYYY-MM-DD') and DATETIME ('YYYY-MM-DD HH:MM:SS', Baghdad local time),
--     always generated by the application and passed as parameters.
--   * Booleans are INTEGER 0/1 (TINYINT(1) in MySQL).
--   * For MySQL: replace "INTEGER PRIMARY KEY AUTOINCREMENT" with "INT AUTO_INCREMENT PRIMARY KEY"
--     and drop "IF NOT EXISTS" from CREATE INDEX. CHECK constraints need MySQL 8.0.16+.

CREATE TABLE IF NOT EXISTS users (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  username      VARCHAR(50)  NOT NULL UNIQUE,
  full_name     VARCHAR(100) NOT NULL,
  password_hash VARCHAR(100) NOT NULL,
  role          VARCHAR(20)  NOT NULL CHECK (role IN ('admin', 'pharmacist', 'cashier')),
  active        INTEGER      NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
  created_at    DATETIME     NOT NULL
);

CREATE TABLE IF NOT EXISTS sessions (
  token_hash VARCHAR(64) PRIMARY KEY,
  user_id    INTEGER     NOT NULL REFERENCES users(id),
  created_at DATETIME    NOT NULL,
  expires_at DATETIME    NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);

CREATE TABLE IF NOT EXISTS settings (
  setting_key   VARCHAR(50)  PRIMARY KEY,
  setting_value VARCHAR(500) NOT NULL
);

-- Row-locked counters (e.g. invoice numbers per year); safe under concurrency in MySQL too.
CREATE TABLE IF NOT EXISTS sequences (
  name  VARCHAR(50) PRIMARY KEY,
  value INTEGER     NOT NULL
);

CREATE TABLE IF NOT EXISTS categories (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  name       VARCHAR(100) NOT NULL UNIQUE,
  sort_order INTEGER      NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS products (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  brand_name   VARCHAR(150) NOT NULL,
  generic_name VARCHAR(150) NOT NULL,
  dosage_form  VARCHAR(50)  NOT NULL,
  pack_size    VARCHAR(50)  NOT NULL DEFAULT '',
  barcode      VARCHAR(50)  UNIQUE,
  category_id  INTEGER      REFERENCES categories(id),
  sale_price   INTEGER      NOT NULL CHECK (sale_price >= 0),
  min_stock    INTEGER      NOT NULL DEFAULT 0 CHECK (min_stock >= 0),
  requires_rx  INTEGER      NOT NULL DEFAULT 0 CHECK (requires_rx IN (0, 1)),
  active       INTEGER      NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
  created_at   DATETIME     NOT NULL,
  updated_at   DATETIME     NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_products_category ON products(category_id);

CREATE TABLE IF NOT EXISTS suppliers (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  name       VARCHAR(150) NOT NULL UNIQUE,
  phone      VARCHAR(30),
  address    VARCHAR(250),
  notes      VARCHAR(500),
  active     INTEGER      NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
  created_at DATETIME     NOT NULL
);

CREATE TABLE IF NOT EXISTS purchases (
  id                  INTEGER PRIMARY KEY AUTOINCREMENT,
  supplier_id         INTEGER      NOT NULL REFERENCES suppliers(id),
  supplier_invoice_no VARCHAR(50),
  purchase_date       DATE         NOT NULL,
  total               INTEGER      NOT NULL CHECK (total >= 0),
  notes               VARCHAR(500),
  user_id             INTEGER      NOT NULL REFERENCES users(id),
  created_at          DATETIME     NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_purchases_supplier ON purchases(supplier_id);
CREATE INDEX IF NOT EXISTS idx_purchases_date ON purchases(purchase_date);

CREATE TABLE IF NOT EXISTS purchase_items (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  purchase_id INTEGER     NOT NULL REFERENCES purchases(id),
  product_id  INTEGER     NOT NULL REFERENCES products(id),
  batch_no    VARCHAR(50) NOT NULL,
  expiry_date DATE        NOT NULL,
  quantity    INTEGER     NOT NULL CHECK (quantity > 0),
  unit_cost   INTEGER     NOT NULL CHECK (unit_cost >= 0),
  line_total  INTEGER     NOT NULL CHECK (line_total >= 0)
);
CREATE INDEX IF NOT EXISTS idx_purchase_items_purchase ON purchase_items(purchase_id);

-- Stock lives here. Product stock = SUM(quantity) of batches whose expiry_date >= today.
CREATE TABLE IF NOT EXISTS batches (
  id               INTEGER PRIMARY KEY AUTOINCREMENT,
  product_id       INTEGER     NOT NULL REFERENCES products(id),
  batch_no         VARCHAR(50) NOT NULL,
  expiry_date      DATE        NOT NULL,
  quantity         INTEGER     NOT NULL CHECK (quantity >= 0),
  unit_cost        INTEGER     NOT NULL CHECK (unit_cost >= 0),
  purchase_item_id INTEGER     REFERENCES purchase_items(id),
  received_at      DATETIME    NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_batches_product_expiry ON batches(product_id, expiry_date);

CREATE TABLE IF NOT EXISTS supplier_returns (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  supplier_id INTEGER      NOT NULL REFERENCES suppliers(id),
  return_date DATE         NOT NULL,
  total       INTEGER      NOT NULL CHECK (total >= 0),
  reason      VARCHAR(500) NOT NULL,
  user_id     INTEGER      NOT NULL REFERENCES users(id),
  created_at  DATETIME     NOT NULL
);

CREATE TABLE IF NOT EXISTS supplier_return_items (
  id                 INTEGER PRIMARY KEY AUTOINCREMENT,
  supplier_return_id INTEGER NOT NULL REFERENCES supplier_returns(id),
  batch_id           INTEGER NOT NULL REFERENCES batches(id),
  quantity           INTEGER NOT NULL CHECK (quantity > 0),
  unit_cost          INTEGER NOT NULL CHECK (unit_cost >= 0),
  line_total         INTEGER NOT NULL CHECK (line_total >= 0)
);
CREATE INDEX IF NOT EXISTS idx_supplier_return_items_return ON supplier_return_items(supplier_return_id);

CREATE TABLE IF NOT EXISTS customers (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  name       VARCHAR(150) NOT NULL,
  phone      VARCHAR(30)  UNIQUE,
  balance    INTEGER      NOT NULL DEFAULT 0,
  created_at DATETIME     NOT NULL
);

-- One open shift per user at a time (enforced in the application, inside a transaction).
CREATE TABLE IF NOT EXISTS shifts (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id       INTEGER      NOT NULL REFERENCES users(id),
  opened_at     DATETIME     NOT NULL,
  opening_cash  INTEGER      NOT NULL CHECK (opening_cash >= 0),
  closed_at     DATETIME,
  expected_cash INTEGER,
  counted_cash  INTEGER      CHECK (counted_cash IS NULL OR counted_cash >= 0),
  difference    INTEGER,
  notes         VARCHAR(500)
);
CREATE INDEX IF NOT EXISTS idx_shifts_user ON shifts(user_id, closed_at);

CREATE TABLE IF NOT EXISTS customer_payments (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  customer_id INTEGER      NOT NULL REFERENCES customers(id),
  amount      INTEGER      NOT NULL CHECK (amount > 0),
  method      VARCHAR(10)  NOT NULL CHECK (method IN ('cash', 'card')),
  shift_id    INTEGER      REFERENCES shifts(id),
  paid_at     DATETIME     NOT NULL,
  user_id     INTEGER      NOT NULL REFERENCES users(id),
  note        VARCHAR(250)
);
CREATE INDEX IF NOT EXISTS idx_customer_payments_customer ON customer_payments(customer_id);
CREATE INDEX IF NOT EXISTS idx_customer_payments_shift ON customer_payments(shift_id);

CREATE TABLE IF NOT EXISTS sales (
  id              INTEGER PRIMARY KEY AUTOINCREMENT,
  invoice_no      VARCHAR(20)  NOT NULL UNIQUE,
  sold_at         DATETIME     NOT NULL,
  customer_id     INTEGER      REFERENCES customers(id),
  subtotal        INTEGER      NOT NULL CHECK (subtotal >= 0),
  discount_pct    DECIMAL(5,2) NOT NULL DEFAULT 0 CHECK (discount_pct >= 0 AND discount_pct <= 100),
  discount_amount INTEGER      NOT NULL DEFAULT 0 CHECK (discount_amount >= 0),
  total           INTEGER      NOT NULL CHECK (total >= 0),
  payment_method  VARCHAR(10)  NOT NULL CHECK (payment_method IN ('cash', 'card', 'debt')),
  shift_id        INTEGER      NOT NULL REFERENCES shifts(id),
  user_id         INTEGER      NOT NULL REFERENCES users(id)
);
CREATE INDEX IF NOT EXISTS idx_sales_sold_at ON sales(sold_at);
CREATE INDEX IF NOT EXISTS idx_sales_customer ON sales(customer_id);
CREATE INDEX IF NOT EXISTS idx_sales_shift ON sales(shift_id);

-- A sale can carry several prescriptions; each prescription-only sale_item points to one.
CREATE TABLE IF NOT EXISTS prescriptions (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  sale_id      INTEGER      NOT NULL REFERENCES sales(id),
  rx_number    VARCHAR(50)  NOT NULL,
  doctor_name  VARCHAR(150) NOT NULL,
  patient_name VARCHAR(150) NOT NULL,
  rx_date      DATE         NOT NULL,
  image_path   VARCHAR(250),
  created_at   DATETIME     NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_prescriptions_sale ON prescriptions(sale_id);

-- One row per (product, batch) actually taken; a cart line can split across batches (FEFO).
CREATE TABLE IF NOT EXISTS sale_items (
  id              INTEGER PRIMARY KEY AUTOINCREMENT,
  sale_id         INTEGER NOT NULL REFERENCES sales(id),
  product_id      INTEGER NOT NULL REFERENCES products(id),
  batch_id        INTEGER NOT NULL REFERENCES batches(id),
  prescription_id INTEGER REFERENCES prescriptions(id),
  quantity        INTEGER NOT NULL CHECK (quantity > 0),
  unit_price      INTEGER NOT NULL CHECK (unit_price >= 0),
  unit_cost       INTEGER NOT NULL CHECK (unit_cost >= 0),
  line_total      INTEGER NOT NULL CHECK (line_total >= 0),
  returned_qty    INTEGER NOT NULL DEFAULT 0 CHECK (returned_qty >= 0 AND returned_qty <= quantity)
);
CREATE INDEX IF NOT EXISTS idx_sale_items_sale ON sale_items(sale_id);
CREATE INDEX IF NOT EXISTS idx_sale_items_product ON sale_items(product_id);

CREATE TABLE IF NOT EXISTS sale_returns (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  sale_id       INTEGER      NOT NULL REFERENCES sales(id),
  returned_at   DATETIME     NOT NULL,
  reason        VARCHAR(500) NOT NULL,
  refund_amount INTEGER      NOT NULL CHECK (refund_amount >= 0),
  refund_method VARCHAR(10)  NOT NULL CHECK (refund_method IN ('cash', 'card', 'debt')),
  shift_id      INTEGER      REFERENCES shifts(id),
  user_id       INTEGER      NOT NULL REFERENCES users(id)
);
CREATE INDEX IF NOT EXISTS idx_sale_returns_sale ON sale_returns(sale_id);
CREATE INDEX IF NOT EXISTS idx_sale_returns_returned_at ON sale_returns(returned_at);
CREATE INDEX IF NOT EXISTS idx_sale_returns_shift ON sale_returns(shift_id);

CREATE TABLE IF NOT EXISTS sale_return_items (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  return_id     INTEGER NOT NULL REFERENCES sale_returns(id),
  sale_item_id  INTEGER NOT NULL REFERENCES sale_items(id),
  quantity      INTEGER NOT NULL CHECK (quantity > 0),
  refund_amount INTEGER NOT NULL CHECK (refund_amount >= 0)
);
CREATE INDEX IF NOT EXISTS idx_sale_return_items_return ON sale_return_items(return_id);

-- Every stock change. qty_change is signed (+ in, - out). ref_id points to the
-- sale / purchase / return row depending on movement_type.
CREATE TABLE IF NOT EXISTS stock_movements (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  product_id    INTEGER      NOT NULL REFERENCES products(id),
  batch_id      INTEGER      NOT NULL REFERENCES batches(id),
  movement_type VARCHAR(20)  NOT NULL CHECK (movement_type IN
                  ('opening', 'sale', 'return', 'purchase', 'adjustment', 'write_off', 'supplier_return')),
  qty_change    INTEGER      NOT NULL CHECK (qty_change <> 0),
  reason        VARCHAR(500),
  ref_id        INTEGER,
  user_id       INTEGER      NOT NULL REFERENCES users(id),
  created_at    DATETIME     NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_stock_movements_product ON stock_movements(product_id, created_at);
CREATE INDEX IF NOT EXISTS idx_stock_movements_batch ON stock_movements(batch_id);
